//go:build !purego

package sha1

//go:generate sh -c "cd _asm && go run . -out ../sha1block_ssse3_amd64.s"

// blockSSSE3 is the SSSE3 block function generated by _asm.
//
//go:noescape
func blockSSSE3(dig *[5]uint32, p []byte)

// blockAMD64 is the scalar block function from Go 1.24.
//
//go:noescape
func blockAMD64(dig *[5]uint32, p []byte)

func defaultImpl() implementation {
	return chooseImpl(x86)
}

// chooseImpl returns the code path for a CPU with the features f.
func chooseImpl(f cpuFeatures) implementation {
	// crypto/sha1 uses assembly under these conditions, copied from Go
	// 1.26's crypto/sha1/sha1block_amd64.go. Its SHA-NI code also needs
	// AVX.
	useAVX2 := f.hasAVX && f.hasAVX2 && f.hasBMI1 && f.hasBMI2
	useSHANI := f.hasAVX && f.hasSHA && f.hasSSE41 && f.hasSSSE3
	switch {
	case useAVX2 || useSHANI:
		return implStdlib
	case f.hasSSSE3:
		return implSSSE3
	default:
		return implScalar
	}
}

// supportedImpls returns the code paths that can run on this machine.
func supportedImpls() []implementation {
	impls := []implementation{implStdlib, implGeneric, implScalar}
	if x86.hasSSSE3 {
		impls = append(impls, implSSSE3)
	}
	return impls
}

func block(dig *digest, p []byte) {
	switch impl {
	case implSSSE3:
		blockSSSE3(&dig.h, p)
	case implScalar:
		blockAMD64(&dig.h, p)
	default:
		blockGeneric(dig, p)
	}
}
